def revenue_by_region(df):
    """Calculate total revenue generated by each region."""

    result = df.groupby("Region")["Revenue"].sum()

    return result.sort_values(ascending=False)

def orders_by_region(df):
    """Calculate the number of unique orders in each region."""

    result = df.groupby("Region")["Order_ID"].nunique()

    return result.sort_values(ascending=False)

def average_order_value_by_region(df):
    """Calculate average revenue per order in each region."""

    revenue = df.groupby("Region")["Revenue"].sum()
    orders = df.groupby("Region")["Order_ID"].nunique()

    result = revenue / orders

    return result.sort_values(ascending=False)


